import React, { useState, useMemo } from "react";
import { FaInstagram, FaFacebookF, FaTwitter } from "react-icons/fa";
import {
  Gem,
  Sparkles,
  CircleDot,
  Star,
  Link2,
  Watch,
  ShoppingBag,
  Search,
  User,
  Menu,
 
} from "lucide-react";


/* ============================================================
   DESIGN TOKENS
   A boutique jewelry-case palette: deep espresso background,
   champagne gold accent, ivory type. Replace freely if this
   project already has its own token set.
   ============================================================ */


const fontImport = `
  @import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;1,400&family=Jost:wght@300;400;500;600&display=swap');
`;

/* ============================================================
   CATEGORY DATA
   ============================================================ */
const CATEGORIES = [
  { id: "All", label: "All", icon: Sparkles },
  { id: "Rings", label: "Rings", icon: Gem },
  { id: "Necklaces", label: "Necklaces", icon: Sparkles },
  { id: "Bracelets", label: "Bracelets", icon: CircleDot },
  { id: "Earrings", label: "Earrings", icon: Star },
  { id: "Chains", label: "Chains", icon: Link2 },
  { id: "Watches", label: "Watches", icon: Watch },
];

/* ============================================================
   PRODUCT DATA
   "image" paths start with "/" so they resolve from the app's
   public root. Put the matching files in: public/images/...
   (e.g. public/images/ring_1.jpeg). If a file is missing or
   fails to load, the card falls back to the category icon
   automatically, so nothing ever breaks.
   ============================================================ */
const PRODUCTS = [
  { id: 1, name: "Aria Solitaire Ring", category: "Rings", price: 189, icon: Gem, badge: "New", image: "./images/ring_1.jpeg" },
  { id: 2, name: "Verona Twist Band", category: "Rings", price: 145, icon: Gem, image: "/images/ring_3.jpeg" },
  { id: 3, name: "Celeste Starfish Ring", category: "Rings", price: 165, icon: Gem, image: "/images/ring_2.jpeg" },
  { id: 4, name: "Celeste Diamond Necklace", category: "Necklaces", price: 310, icon: Sparkles, badge: "Bestseller", image: "/images/chain_2.png" },
  { id: 5, name: "Noir Heart Necklace", category: "Necklaces", price: 175, icon: Sparkles, image: "/images/chain_3.png" },
  { id: 6, name: "Luna Moonstone Necklace", category: "Necklaces", price: 220, icon: Sparkles, badge: "New", image: "/images/chain_4.png" },
